<header class="admin-header"><div><span class="eyebrow">NCF Super Admin</span><h1>Overview</h1></div><span><?=e(auth()['full_name'])?></span></header><section class="stat-grid"><?php foreach($stats as $label=>$value):?><article class="stat"><span><?=e($label)?></span><strong><?=e($value)?></strong></article><?php endforeach;?></section><section class="admin-panel"><h2>Recent activity</h2><div class="table-wrap"><table><thead><tr><th>Time</th><th>Administrator</th><th>Action</th><th>Record</th></tr></thead><tbody><?php foreach($activities as $a):?><tr><td><?=e($a['created_at'])?></td><td><?=e($a['actor']??'System')?></td><td><?=e($a['action'])?></td><td><?=e(($a['entity_type']??'').' #'.($a['entity_id']??''))?></td></tr><?php endforeach;?></tbody></table></div></section>
